<?php
$statusBadge = static function (string $status): string {
    return in_array($status, ['confirmed', 'checked_in', 'in_queue', 'in_consultation'], true)
        ? 'badge-success'
        : ($status === 'cancelled' || $status === 'no_show' ? 'badge-secondary' : 'badge-light');
};
?>
<div class="patient-appointments-grid">
    <?php foreach ($appointments as $appointment): ?>
        <?php $editable = in_array($appointment['status'], ['scheduled', 'confirmed'], true) && (string) $appointment['appointment_date'] >= $today; ?>
        <article class="patient-appointment-card">
            <div class="patient-appointment-card-head"><div><span class="patient-eyebrow">Appointment</span><h3 title="<?= esc($appointment['appointment_number'] ?? '') ?>"><?= esc($appointment['appointment_number'] ?? '—') ?></h3></div><span class="badge <?= $statusBadge((string) $appointment['status']) ?> patient-status-badge"><?= esc($label((string) $appointment['status'])) ?></span></div>
            <div class="patient-appointment-card-doctor"><span class="patient-avatar" aria-hidden="true"><?= esc(strtoupper(substr((string) ($appointment['doctor_first_name'] ?? 'D'), 0, 1))) ?></span><div><strong>Dr. <?= esc(trim(($appointment['doctor_first_name'] ?? '') . ' ' . ($appointment['doctor_last_name'] ?? ''))) ?></strong><small><?= esc($appointment['specialization'] ?: 'Specialization not recorded') ?></small></div></div>
            <dl class="patient-appointment-card-details"><div><dt>Date / time</dt><dd><?= esc($formatDate($appointment['appointment_date'] ?? null)) ?> · <?= esc(substr((string) ($appointment['appointment_time'] ?? ''), 0, 5) ?: '—') ?></dd></div><div><dt>Service / queue</dt><dd><?= esc($appointment['service_name'] ?: $label((string) $appointment['appointment_type'])) ?> · <?= esc((string) ($appointment['queue_position'] ?? '—')) ?></dd></div><div><dt>Type</dt><dd><?= esc($label((string) ($appointment['appointment_type'] ?? ''))) ?></dd></div></dl>
            <p class="patient-card-meta"><i class="fa-solid fa-circle-exclamation mr-1" aria-hidden="true"></i>Created <?= esc($formatDate($appointment['created_at'] ?? null)) ?> · Updated <?= esc($formatDate($appointment['updated_at'] ?? null)) ?></p>
            <div class="patient-appointment-card-actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-appointment-view" type="button" data-id="<?= (int) $appointment['id'] ?>" data-toggle="modal" data-target="#patient-appointment-detail-modal">View appointment</button><?php if ($editable): ?><button class="dropdown-item patient-appointment-reschedule" type="button" data-id="<?= (int) $appointment['id'] ?>" data-date-display="<?= esc($formatDate($appointment['appointment_date'] ?? null)) ?>" data-time="<?= esc(substr((string) ($appointment['appointment_time'] ?? ''), 0, 5)) ?>">Reschedule</button><button class="dropdown-item text-danger patient-appointment-cancel" type="button" data-id="<?= (int) $appointment['id'] ?>">Cancel appointment</button><?php endif; ?><?php if ((int) ($appointment['prescription_id'] ?? 0) > 0): ?><a class="dropdown-item" href="<?= base_url('patient/prescriptions?prescription_id=' . (int) $appointment['prescription_id']) ?>">View prescription</a><?php endif; ?><?php if ((int) ($appointment['invoice_id'] ?? 0) > 0): ?><a class="dropdown-item" href="<?= base_url('patient/invoices?invoice_id=' . (int) $appointment['invoice_id']) ?>">View invoice / payment</a><?php endif; ?><?php if ((int) ($appointment['order_id'] ?? 0) > 0): ?><a class="dropdown-item" href="<?= base_url('patient/orders?order_id=' . (int) $appointment['order_id']) ?>">View order / delivery</a><?php endif; ?></div></div></div>
        </article>
    <?php endforeach; ?>
    <?php if ($appointments === []): ?><div class="patient-empty-state"><i class="bi bi-calendar-x" aria-hidden="true"></i><strong>No appointments found</strong><span>Try clearing filters or book a new appointment.</span></div><?php endif; ?>
</div>
